// @pinnedness: unpinned
// @stability: very-unstable
//! @ai: generated
//! The mxx DSL programs that are the **source of truth** for
//! mxx-autogenerated `volar-spec` elements (Phase 1 of
//! `docs/mxx-cutover-plan.md`).
//!
//! Each function here builds an mxx program with `mxx-dsl`, freezes it, and
//! validates it under concrete parameter bindings (plan §7 default: bake
//! symbolic parameters at freeze time). The validated graph is what
//! [`crate::lower_validated_to_module`] lowers; the same graph is what the
//! Phase-2 Lean transport references via `mxx_ir_core::lean`, so spec
//! element, Rust output, and Lean relation can never drift apart.
//!
//! Program naming is load-bearing: the element's file name, function name,
//! and Lean scope name all derive from the [`ElementSpec`] fields, and the
//! generated file's banner records the mxx pin.

use mxx_dsl::{BuiltGraph, DslContext, Ring};
use mxx_ir_core::ParamEnv;
use mxx_ir_core::validate::ValidatedGraph;

use crate::InteropError;

/// One mxx-sourced spec element: its program plus the names the generated
/// artifacts carry.
pub struct ElementSpec {
    /// Element name, used for the generated file and Lean scope
    /// (`mxx_<name>`).
    pub element: &'static str,
    /// Name of the lowered top-level function.
    pub function: &'static str,
    /// Build + validate the program.
    pub build: fn() -> Result<(BuiltGraph, ValidatedGraph), InteropError>,
}

/// Every mxx-sourced spec element, in generation order.
pub fn elements() -> Vec<ElementSpec> {
    vec![ElementSpec {
        element: "lwe",
        function: "mxx_lwe_sample",
        build: lwe_sample,
    }]
}

/// LWE sample construction `b = A * s + e` over a prime ring
/// `Z_q[X]/(X^N + 1)` — the concrete, mxx-expressible core of
/// `volar-spec`'s generic `lwe::LweSample::sample`.
///
/// Toy parameters for Phase 1: a small modulus keeps the cross-test against
/// the generic implementation exhaustive-friendly. Cryptographically
/// meaningful parameter sets arrive with symbolic-parameter support
/// (plan §7); this element is a pipeline skeleton, not a parameter claim.
fn lwe_sample() -> Result<(BuiltGraph, ValidatedGraph), InteropError> {
    const MODULUS: u64 = 257;
    const RING_DIM: u32 = 1;
    const M: usize = 4;
    const N: usize = 3;
    let ctx = DslContext::new("lwe-sample");
    let ring = Ring::from_crt_moduli(vec![MODULUS.into()], RING_DIM);
    let a = ring.input("matrix", (M, N));
    let s = ring.input("secret", (N, 1));
    let e = ring.input("noise", (M, 1));
    let b = a * s + e;
    let built = ctx
        .output("b", b)
        .and_then(DslContext::build)
        .map_err(|e| InteropError::Expr(format!("build lwe-sample: {e}")))?;
    let validated = built
        .validate(&ParamEnv::default())
        .map_err(|e| InteropError::Expr(format!("validate lwe-sample: {e}")))?;
    Ok((built, validated))
}
